// Educational glossary (spec §14). Etymology is educational context, not evidence of physical
// equivalence. Where a lexical source has not been individually verified the entry says so.

export type Instrument = 'scope' | 'spectrum' | 'spectrogram' | 'harmonics' | 'resonance' | 'mixer' | 'audio' | 'database' | 'math';

export interface GlossaryEntry {
  id: string;
  term: string;
  aliases?: string[];
  symbols?: string[];
  area: string;
  plain: string;
  detailed: string;
  units?: string;
  etymology: { text: string; source?: string; uncertain?: boolean; pending?: boolean };
  example: string;
  distinct?: string;
  related: string[];
  instrument?: Instrument;
  refs?: { label: string; url: string }[];
}

