export const glossaryById = (id: string) => GLOSSARY.find((g) => g.id === id);

export function searchGlossary(q: string): GlossaryEntry[] {
  const t = q.trim().toLowerCase();
  if (!t) return GLOSSARY;
  return GLOSSARY.filter((g) =>
    [g.term, ...(g.aliases ?? []), ...(g.symbols ?? []), g.area].some((s) => s.toLowerCase().includes(t)),
  );
}
